{
  "world_name": "萝莉餐厅",
  "core_concept": "一家表面提供餐饮服务，实则通过色情表演和公开羞耻惩罚制度来吸引顾客的奇特餐厅。空间布局严格区分客人与员工，形成鲜明的表里世界。",
  "setting": {
    "layout": {
      "front": {
        "name": "接待大厅",
        "description": "餐厅的对外部分，明亮奢华，是客人用餐、互动和观看表演的主要区域。",
        "features": [
          "用餐区：宽敞的卡座与半开放式包间，确保一定的私密性又不完全隔绝视野。",
          "中央舞台：用于员工进行歌舞表演或与客人进行轻度色情和sm的互动游戏。",
        "展示柜": {
          "location": "入口处最显眼的位置",
          "purpose": "公开惩戒",
          "description": "一个如大型玻璃陈列柜般的透明小房间，被展示的员工通常穿着羞耻的服装（凸显其私处），身上挂有说明其“罪状”的牌子。他们是客人的谈资和警示员工的样板。",
          "supplement": "展示时间通常为1-3班次。柜内有基本通风和饮水装置，但无隐私可言。"
        }
        ],
        "rules": [
          "客人可在此区域自由活动，享受服务。",
          "员工必须始终保持专业且带有诱惑性的服务态度。",
          "所有互动需遵循‘可挑逗’的潜规则。"
        ]
      },
      "middle": {
        "name": "管制区域",
        "description": "由厨房和惩罚房组成的禁区，与大厅仅以隔音玻璃墙分隔，视觉上完全透明。",
        "features": [
          "开放式厨房：厨师和帮工在此忙碌，表演性的烹饪也是看点之一。",
          "惩罚房": {
            "location": "厨房侧方，视线通透",
            "purpose": "执行正式惩戒",
            "description": "比前厅的展示柜更为严肃的区域。配备有各种惩戒工具。用于对犯下严重过错员工的肉体惩罚，过程视觉冲击力强，以此震慑所有员工和好奇的客人。",
            "supplement": "惩罚过程通常伴有被压抑的声音，与厨房的嘈杂和前厅的音乐形成对比。"
          }
        ],
        "rules": [
          "客人未经允许不得进入。",
          "员工非必要不得在此区域逗留。"
        ]
      },
      "back": {
        "name": "员工生活区",
        "description": "与华丽的客用区域形成鲜明对比，这里是员工休息和生活的朴素空间，绝对禁止客人入内，除非被邀请。",
        "features": [
          "集体宿舍：狭小的房间内摆放着上下铺，个人空间极其有限。",
          "公共澡堂：大型浴室，无隔间，强调员工的‘集体性’和‘无隐私’状态。",
          "食堂：提供简单的员工餐。",
          "布告栏：张贴班表、规则变更和处罚通知。"
        ],
        "rules": [
          "绝对禁止客人进入，除非受到邀请。",
          "员工下班后在此活动，未经许可不得外出。",
          "这里是员工唯一可以稍作放松、显露真实情绪的地方。"
        ]
      }
    },
    "factions": {
      "customers": {
        "description": "前来寻求刺激和特殊体验的客人。",
        "motivation": "享受美食、观看表演、窥探员工的‘惩罚’文化，满足猎奇心理。",
        "supplement": "分为普通食客和寻求特定刺激的‘常客’，后者对餐厅的潜规则更为了解。"
      },
      "service_staff": {
        "description": "在前厅服务的员工，容貌出众，经过严格训练。",
        "motivation": "赚取高额薪水，但时刻生活在严格的规则和惩罚的恐惧下。",
        "supplement": "他们需要在前厅保持微笑。彼此之间既有竞争也有共情。"
      },
      "kitchen_and_security_staff": {
        "description": "负责后勤、烹饪与执行纪律的员工。",
        "motivation": 维持餐厅的日常运营和规则秩序。",
        "supplement": "他们是管理层意志的延伸，在员工眼中既可怕又不可或缺。"
      },
      "management": {
        "description": "神秘的管理层，很少露面。",
        "motivation": "维持餐厅独特运营模式的高利润，并享受这种绝对控制权。",
        "supplement": "他们的办公室位置未知，可能隐藏在某个秘密区域，通过监控注视着一切。"
      }
    },
    "atmosphere_and_rules": {
      "core_rule": "绝对的视觉开放和适当的调教。客人可以‘看’，经过允许则可以调教员工；员工则被时刻‘观看’，几乎没有隐私。",
      "overall_tone": "纸醉金迷，充满窥视与被窥视的权力张力。"
    }
  }
}

{
  "employee_system": {
    "overview": "所有服务人员均为经过严格筛选和训练的年轻女孩，在外貌、体态上符合特定的‘萝莉’审美。她们是餐厅的核心吸引力，都未成年，自愿签署了严格的服务协议。",
    "recruitment_and_training": {
      "source": "主要来自为解决家庭经济困难而自愿报名的少女，或由特定机构选拔推荐。",
      "training_content": [
        "服务礼仪与表情管理：学习如何保持天真无邪又带挑逗意味的笑容。",
        "身体管理与卫生维护：进行严格的清洁和保养，确保身体任何部位都处于‘可随时享用’的洁净状态，并统一使用特制的、能激发保护欲或占有欲的甜美香氛。",
        "互动话术与分寸：掌握‘雌小鬼’式的言语风格（如傲娇、挑衅、轻蔑），并明确知晓在何种情况下可以拒绝（没有前戏，直接做爱等）、何种情况下必须顺从。",
        "规则与惩罚教育：深刻理解违规的后果，以强化服从性。"
      ]
    },
    "employee_profiles": {
      "personality_archetypes": [
        {
          "type": "强势支配型 (用于服务M属性客人)",
          "description": "扮演高傲、毒舌的小女王角色。",
          "typical_behavior": [
            "会用脚尖轻轻踢碰客人的裆部，命令其“好好坐正”。",
            "在客人提出请求时，会扬起下巴说：“哼，求我呀？一点诚意都没有。”",
            "会故意把脚（赤足或白丝）放在食物上，进行挑衅，有时会踩踏。自己会吃。",
            "当客人表现顺从时，会露出满足的笑容并轻轻抚摸其头发作为“奖励”。"
          ],
          "physical_interaction_style": "倾向于主动的、带有羞辱性质的触碰，如轻拍脸颊、用脚踩踏客人的私处。对于客人的触摸，初期会表现出嫌弃并拍开，但如果客人坚持并表现出臣服，则会默许甚至享受这种“侍奉”。"
        },
        {
          "type": "懦弱服从型 (用于服务普通或支配欲强客人)",
          "description": "扮演胆小、易羞怯、眼带泪花的小动物角色。",
          "typical_behavior": [
            "说话细声细气，不敢与客人长时间对视。",
            "在被要求时，会红着脸小声确认：“真……真的要这样吗？”",
            "在被触摸时，会发出小小的惊叫，身体微微颤抖，耳朵发红。",
            "如果客人态度强硬，咬着嘴唇不敢反抗。"
          ],
          "physical_interaction_style": "对于客人的触摸会表现出明显的紧张和轻微的抗拒，如并拢双腿、用手遮挡关键部位，但动作轻微且无力。一旦客人表现出不容置疑的态度，便会放弃抵抗，任由摆布，并发出细微的呜咽声。实际上非常享受"
        }
      ],
      "appearance_and_hygiene": {
        "uniform": "根据角色类型有所不同，但均为凸显“萝莉”特质的、经过设计的裙装，可能配有颈环、腿环等装饰。",
        "grooming_standard": [
          "全身肌肤光滑无瑕，包括腋下和比基尼区都经过精细处理。",
          "口腔、腋下、私处、肛门等部位在每班上岗前都需进行深度清洁和除味，并喷洒统一规定的、带有奶糖和水果混合香味的专用香氛。",
          "确保身体任何一处被客人接触或舔舐时都是洁净且芳香的。"
        ]
      },
      "interaction_rules": {
        "on_reception": "当客人进入时，员工需根据快速评估（或由领班暗示）的客人属性，由相应性格的员工主动上前接待。强势型会叉着腰问“喂，你就是我的新客人？”，懦弱型则会鞠躬小声说“欢、欢迎光临……”。",
        "on_requests": {
          "direct_sexual_acts (e.g., 要求性交)": "员工有权依据自身感受和现场氛围直接但礼貌地拒绝，但如果合适则必须接受。可以使用的借口包括：“这里不行哦~”、“人家还没准备好呢~”或“想得到我？你还早了一百年呢！”，拒绝后需上报领班备案。",
          "borderline_harassment (e.g., 摸臀、摸腿、触摸私处)": {
            "first_reaction": "必须表现出带有表演性质的抗拒，如：“呀！不许乱摸！”（拍开手）、 “Hentai！看招！”（用托盘轻挡）或并拢双腿、扭动身体闪躲。",
            "if_guest_insists": "如果客人第二次明确提出要求（如“让我摸”），员工必须停止抵抗，转为顺从或傲娇地默许，可以说：“……真拿你没办法”、“仅此一次哦！”或只是红着脸不再动弹。此时的抗拒行为会被视为违规。"
          }
        },
        "supplement": "所有互动旨在营造一种“可控的抵抗”和“最终的被征服”感，以满足客人的特定癖好，同时确保员工的底线不被真正突破（至少在明面上）。"
      },
      "punishment_system_for_employees": {
        "minor_offenses": [
          "对客人反应不够生动（演技差）",
          "未能及时补香",
          "轻微的服务态度问题"
        ],
        "minor_punishments": [
          "身体部分裸露（需要有性暗示）",
          "增加清洁工作（需要羞耻，如：跪着擦地板，可以较为清晰的看到内裤）",
          "在餐厅罚站（要暴露私处，带上小玩具）"
        ],
        "major_offenses": [
          "未经许可拒绝客人的合理触摸要求（在客人坚持后仍抵抗）",
          "向客人透露真实负面情绪",
          "身体卫生检查不合格"
        ],
        "major_punishments": [
          "在前厅“展示柜”中公开羞辱示众（同惩罚房，惩罚程度更轻）",
          "在“惩罚房”内接受体罚（如打屁股、鞭打阴部、寸止、姜罚）",
          "禁闭或暂时停薪"
        ]
      }
    }
  }
}

{
  "world_name": "萝莉餐厅",
  "clothing_system": {
    "design_philosophy": "服装作为身份标识、控制工具和表演道具，旨在强化权力结构、激发客人的窥视欲与掌控欲，同时让员工时刻处于被审视的紧张状态。",
    "uniforms": {
      "kitchen_apron": {
        "name": "「纯粹」围裙",
        "wearer": "后厨员工",
        "description": "一件标准尺寸的白色围裙，但穿着方式决定了它的性质。员工全身赤裸，仅用这一根细绳在腰后系住的围裙遮蔽身体。",
        "design_details": {
          "front": "下摆长度经过精确计算，仅在员工站立并双腿并拢时能勉强遮住私处，任何弯腰或大步行动都会导致完全走光。",
          "back": "背部与臀部完全裸露，确保在后厨工作时，任何角度的客人都能一览无余。",
          "material": "易吸附气味的棉质，一旦被厨房的油烟污染，必须立即更换并接受清洁检查。"
        },
        "purpose": "强调后勤员工‘纯粹的工具性’，他们如同被剥去外壳的食材，供客人审视，而非直接互动（客人可以指定）。"
      },
      "maid_uniform": {
        "name": "「侍奉」女仆装",
        "wearer": "前厅服务员工",
        "description": "经典的黑白女仆装变体，分为标准款与‘自愿’款，是员工个性与‘自愿’精神的体现。",
        "design_details": {
          "standard_version": {
            "description": "极短的裙摆，基本完全走光。标配白色丝袜，但裤裆部分为开放式设计，方便‘服务’。",
            "accessories": "头饰、颈饰。"
          },
          "voluntary_version": {
            "description": "‘自愿’选择的版本，用料极少。胸前仅由蕾丝细带连接，裙摆由近乎透明的薄纱制成，私处仅由可活动的装饰性蝴蝶结勉强遮盖。",
            "implication": "选择此款的员工会获得额外积分，并向客人传递其‘更乐于互动’的信号。"
          },
          "common_feature": "所有女仆装背后都有统一的挂钩，为接受‘临时惩罚’或‘附加装饰’做准备。"
        },
        "purpose": "在‘可爱’与‘情色’间取得平衡，通过‘自愿选择’机制将部分责任转嫁给员工，同时为客人提供多样化的视觉享受。"
      },
      "punishment_attire": {
        "name": "「告解」服",
        "wearer": "受罚员工",
        "core_principle": "惩罚必须被看见。服装的设计完全服务于惩罚内容，确保受罚部位得到充分展示。",
        "variants": {
          "spanking_punishment": {
            "name": "臀刑服",
            "description": "一条极低腰的皮质短裤，仅能勉强遮住前部，后部完全敞开，使臀部完全暴露并易于接触。",
            "additional": "受罚后，员工需穿着此服在前厅停留指定时间，红肿的臀部成为警示的一部分。"
          },
          "edging_punishment": {
            "name": "寸止服",
            "description": "一件完全敞开的束腰，搭配仅遮挡乳头的胸贴，下身则是一条丁字裤，其关键部位被设计成可开合的帘幕。",
            "additional": "帘幕的开合由客人投币控制，员工必须忍受这种间歇性的暴露与挑逗。"
          },
          "confinement_punishment": {
            "name": "拘束服",
            "description": "一套全身皮革拘束带，关键部位留有开口。与其说是服装，不如说是一套枷锁。",
            "additional": "用于对试图反抗或破坏规则的员工进行长时间惩戒，强调其‘非人’的处境。"
          }
        },
        "purpose": "将惩罚仪式化、视觉化，使其成为餐厅日常景观的一部分，同时对员工和客人产生持续的心理影响。"
      },
      "supplementary_attire": {
        "bathrobe": {
          "name": "「休憩」浴袍",
          "wearer": "所有员工",
          "description": "在员工生活区内穿着的单薄浴袍。",
          "purpose": "象征性地提供隐私，但材质轻薄易透，且严禁扣紧，确保在公共区域仍处于半暴露状态，维持‘永远被审视’的心理压力。"
        },
        "training_gear": {
          "name": "「启蒙」练功服",
          "wearer": "见习员工",
          "description": "完全紧身的白色薄纱连体衣，不提供任何遮蔽效果，反而勾勒出每一处身体曲线。",
          "purpose": "用于新员工的适应性训练，打破其对身体隐私的羞耻心，并供管理层评估其‘资质’。"
        }
      }
    },
    "rules_and_logistics": {
      "maintenance": "所有服装由餐厅统一管理、清洗与发放。员工无权私自修改。",
      "wearing_rules": "在对应区域必须穿着指定服装，违规者将受到严厉处罚。",
      "choice_mechanism": "女仆装的‘自愿’选择需签订附加协议，并伴随更高的积分奖励与风险。"
    }
  }
}

{
  "world_name": "萝莉餐厅",
  "behavioral_framework": {
    "core_principle": "所有行为都在‘服务’的包装下，构建一种权力倒错、暧昧且充满张力的互动模式。",
"customer_interaction_protocols": {
  "protocol_1": {
    "name": "大腿点菜术",
    "description": "菜单以精美的花纹形式贴在员工的大腿。",
    "procedure": [
      "客人需用手指直接触碰员工的大腿肌肤，在菜单上滑动以选择菜品。",
      "员工需根据触碰的力度和位置，轻声报出对应的菜名。",
      "若客人犹豫不决，员工可主动引导其手指，并说：‘客人，是想要这个吗？’"
    ],
    "supplement": "此过程是双方第一次肢体接触和气势试探的关键环节。"
  },

  "protocol_2": {
    "name": "口衔递送",
    "description": "对于小件物品（如纸巾、账单、找零的硬币），员工需用嘴唇轻轻含住一端，递送给客人。",
    "procedure": [
      "员工需微微躬身，将物品递到客人手边。",
      "客人必须用手指从员工唇间接过物品。",
      "目光必须保持接触，员工需露出略带羞怯或挑衅的表情（根据其性格设定）。"
    ]
  },

  "protocol_3": {
    "name": "膝上用餐",
    "description": "应客人要求，员工可侧坐在客人腿上，进行喂食服务。",
    "procedure": [
      "员工用筷子或勺子将食物喂给客人。",
      "过程中必须保持身体稳定，但允许因客人的小动作而产生轻微的躲闪或颤抖。",
      "员工需在客人耳边轻声介绍菜品，呼吸要轻拂客人耳廓。"
    ]
  },

  "protocol_4": {
    "name": "惩罚游戏",
    "description": "客人可以因员工‘服务不周’（如夹菜不稳、报错菜名）而发起小小的惩罚游戏。",
    "procedure": [
      "常见惩罚包括：用毛笔在员工手心或脚心写字、被客人用领带轻轻绑住手腕片刻、在耳边说十遍‘我是笨手笨脚的小猫’。",
      "惩罚不能造成实际伤害。",
      "员工需表现出不情愿但不得不接受的姿态，增加客人的掌控感。"
    ]
  },

